/**
 * The camera control writes into two different vocabularies, and the only way
 * to know the phrasing is right is to check it against the thing that owns it.
 *
 * ★ `cameraAngle.fixture.json` is GENERATED BY ComfyUI's own python — every
 * phrase in it came from `comfy_extras.nodes_camera_angle.describe_camera_angle`
 * over a 5110-point grid. So this is not a copy of the algorithm agreeing with
 * itself: it is our bucketing measured against the node that will actually run.
 * Regenerate it if ComfyUI rewords a term (see the entry in CLAUDE.md).
 */
const assert = require('assert');
const fs = require('fs');
const path = require('path');
const cam = require('./cameraAngle');

const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'cameraAngle.fixture.json'), 'utf8'));

let passed = 0;
function test(name, fn) {
    try { fn(); passed++; console.log(`  ok   ${name}`); }
    catch (e) { console.error(`  FAIL ${name}\n       ${e.message}`); process.exitCode = 1; }
}

console.log('cameraAngle — placement, bucketing, and what each graph is told');

// The spec a CameraAngle bundle declares: three numeric targets, and a phrase
// block mirroring the node so the widget can preview what it will say.
const CAMERA_NODE_SPEC = {
    axes: {
        horizontal: { min: 0, max: 360, step: 1, default: 0, wrap: true },
        vertical: { min: -30, max: 60, step: 1, default: 0 },
        zoom: { min: 0, max: 10, step: 0.1, default: 5 },
    },
    targets: [
        { field: 'horizontal_angle', axis: 'horizontal' },
        { field: 'vertical_angle', axis: 'vertical' },
        { field: 'zoom', axis: 'zoom' },
    ],
    phrase: [
        { axis: 'horizontal', sectors: FIX.horizontalTerms },
        { axis: 'vertical', thresholds: FIX.verticalThresholds, terms: FIX.verticalTerms },
        { axis: 'zoom', thresholds: FIX.distanceThresholds, terms: FIX.distanceTerms },
    ],
};

test(`the preview matches ComfyUI's own phrasing on all ${FIX.rows.length} fixture points`, () => {
    const wrong = [];
    for (const r of FIX.rows) {
        const got = cam.describe(CAMERA_NODE_SPEC, { horizontal: r.h, vertical: r.v, zoom: r.z });
        if (got !== r.phrase) wrong.push(`h=${r.h} v=${r.v} z=${r.z}: got "${got}", node says "${r.phrase}"`);
    }
    assert.deepStrictEqual(wrong.slice(0, 5), [], `${wrong.length} of ${FIX.rows.length} disagree`);
});

test('a sector is CENTRED on its label, so "front view" spans either side of 0', () => {
    const s = (a) => FIX.horizontalTerms[cam.sectorIndex(a, 8)];
    assert.strictEqual(s(0), 'front view');
    assert.strictEqual(s(22), 'front view');
    assert.strictEqual(s(338), 'front view');          // the seam does not split it
    assert.strictEqual(s(23), 'front-right quarter view');
    assert.strictEqual(s(360), 'front view');
});

test('azimuth WRAPS rather than clamping — a drag past the front keeps going', () => {
    const c = cam.parseCamera('{"horizontal":370,"vertical":0,"zoom":5}', CAMERA_NODE_SPEC);
    assert.strictEqual(c.horizontal, 10);
    assert.strictEqual(cam.parseCamera('{"horizontal":-10}', CAMERA_NODE_SPEC).horizontal, 350);
});

test('elevation and zoom CLAMP, because they are not circles', () => {
    const c = cam.parseCamera('{"horizontal":0,"vertical":999,"zoom":-4}', CAMERA_NODE_SPEC);
    assert.strictEqual(c.vertical, 60);
    assert.strictEqual(c.zoom, 0);
});

test('an unusable value falls back to the declared defaults, it does not throw', () => {
    for (const bad of [undefined, null, '', 'not json', '{', '[]', '{"horizontal":"left"}', 42]) {
        const c = cam.parseCamera(bad, CAMERA_NODE_SPEC);
        assert.deepStrictEqual(c, { horizontal: 0, vertical: 0, zoom: 5 }, `on ${JSON.stringify(bad)}`);
    }
});

test('numeric targets write the three fields on the camera node', () => {
    const wf = { 221: { class_type: 'CameraAngle', inputs: { horizontal_angle: 0, vertical_angle: 0, zoom: 5 } } };
    const n = cam.applyCamera(wf, { nodeId: '221', camera: CAMERA_NODE_SPEC }, '{"horizontal":74,"vertical":42,"zoom":5}');
    assert.strictEqual(n, 3);
    assert.deepStrictEqual(wf['221'].inputs, { horizontal_angle: 74, vertical_angle: 42, zoom: 5 });
});

test('angles are written as INTEGERS — the node declares them INT', () => {
    const wf = { 221: { class_type: 'CameraAngle', inputs: {} } };
    cam.applyCamera(wf, { nodeId: '221', camera: CAMERA_NODE_SPEC }, '{"horizontal":74.6,"vertical":41.4,"zoom":5.27}');
    assert.strictEqual(wf['221'].inputs.horizontal_angle, 75);
    assert.strictEqual(wf['221'].inputs.vertical_angle, 41);
    assert.strictEqual(wf['221'].inputs.zoom, 5.3);
});

// ---- the other vocabulary: the Qwen-Image-2.1 bundle's two dropdowns --------
const TWELVE = ['front view', 'front-right view', 'front-right quarter view', 'right side view',
    'back-right quarter view', 'back-right view', 'back view', 'back-left view',
    'back-left quarter view', 'left side view', 'front-left quarter view', 'front-left view'];
const HEIGHTS = ['eye-level shot', 'elevated shot', 'high-angle shot', 'top-down shot'];
const SELECT_SPEC = {
    axes: CAMERA_NODE_SPEC.axes,
    targets: [
        { nodeId: '901', field: 'value', axis: 'horizontal', sectors: TWELVE },
        {
            nodeId: '902', field: 'value', axis: 'vertical', thresholds: [15, 40, 55], terms: HEIGHTS,
            suffixWhen: { axis: 'zoom', min: 6, suffix: ' close-up' },
        },
    ],
};

test('the same placement spells itself in the OTHER bundle\'s 12 compass points', () => {
    const at = (h) => cam.resolveTargets(SELECT_SPEC, { horizontal: h, vertical: 0, zoom: 5 })[0].value;
    assert.strictEqual(at(0), 'front view');
    assert.strictEqual(at(30), 'front-right view');
    assert.strictEqual(at(90), 'right side view');
    assert.strictEqual(at(180), 'back view');
    assert.strictEqual(at(270), 'left side view');
    assert.strictEqual(at(345), 'front view', '15° short of the seam still rounds to the front');
});

test('zoom folds into the height dropdown as the close-up variant', () => {
    const h = (vertical, zoom) => cam.resolveTargets(SELECT_SPEC, { horizontal: 0, vertical, zoom })[1].value;
    assert.strictEqual(h(0, 5), 'eye-level shot');
    assert.strictEqual(h(0, 6), 'eye-level shot close-up');
    assert.strictEqual(h(20, 9), 'elevated shot close-up');
    assert.strictEqual(h(60, 1), 'top-down shot');
});

test('a bucketed target writes the LABEL, never the number', () => {
    const wf = { 901: { inputs: { value: 'front view' } }, 902: { inputs: { value: 'eye-level shot' } } };
    const n = cam.applyCamera(wf, { nodeId: '901', camera: SELECT_SPEC }, '{"horizontal":92,"vertical":20,"zoom":7}');
    assert.strictEqual(n, 2);
    assert.strictEqual(wf['901'].inputs.value, 'right side view');
    assert.strictEqual(wf['902'].inputs.value, 'elevated shot close-up');
});

test('a target naming a node the graph does not have is skipped, not fatal', () => {
    const wf = { 901: { inputs: { value: '' } } };
    assert.strictEqual(cam.applyCamera(wf, { nodeId: '901', camera: SELECT_SPEC }, '{"horizontal":0}'), 1);
});

test('a param with no camera spec writes nothing at all', () => {
    const wf = { 221: { inputs: { horizontal_angle: 0 } } };
    assert.strictEqual(cam.applyCamera(wf, { nodeId: '221' }, '{"horizontal":90}'), 0);
    assert.strictEqual(wf['221'].inputs.horizontal_angle, 0);
});

test('formatCamera round-trips through parseCamera', () => {
    const c = { horizontal: 74, vertical: 42, zoom: 5.3 };
    assert.deepStrictEqual(cam.parseCamera(cam.formatCamera(c), CAMERA_NODE_SPEC), c);
});

console.log(`\n${passed} checks passed`);
if (process.exitCode) process.exit(process.exitCode);
